import React, { useState } from 'react';
import './Skills.css';

function Skills() {
  const [selectedSkill, setSelectedSkill] = useState(null);

  const technicalSkills = [
    { name: 'Microsoft Office Suite', description: 'Add your experience with Microsoft Office Suite here' },
    { name: 'Google Workspace', description: 'Add your experience with Google Workspace here' },
    { name: 'Project Management Software', description: 'Add your experience with Project Management Software here' },
    { name: 'Data Analysis', description: 'Add your experience with Data Analysis here' },
    { name: 'AI Tools & Technologies', description: 'Add your experience with AI Tools & Technologies here' }
  ];

  const pmSkills = [
    { name: 'Stakeholder Management', description: 'Add your experience with Stakeholder Management here' },
    { name: 'Risk Assessment', description: 'Add your experience with Risk Assessment here' },
    { name: 'Budget Coordination', description: 'Add your experience with Budget Coordination here' },
    { name: 'Timeline Planning', description: 'Add your experience with Timeline Planning here' },
    { name: 'Team Leadership', description: 'Add your experience with Team Leadership here' },
    { name: 'Process Optimization', description: 'Add your experience with Process Optimization here' }
  ];

  const tools = [
    { name: 'Asana', description: 'Add your experience with Asana here' },
    { name: 'Trello', description: 'Add your experience with Trello here' },
    { name: 'Slack', description: 'Add your experience with Slack here' },
    { name: 'Microsoft Teams', description: 'Add your experience with Microsoft Teams here' },
    { name: 'Monday.com', description: 'Add your experience with Monday.com here' },
    { name: 'Excel', description: 'Add your experience with Excel here' }
  ];

  const handleSkillClick = (skill) => {
    setSelectedSkill(selectedSkill?.name === skill.name ? null : skill);
  };

  return (
    <section id="skills" className="skills">
      <h2>Skills & Competencies</h2>

      <div className="skills-grid">
        <div className="skill-category">
          <h3>Technical Skills</h3>
          <div className="skill-list">
            {technicalSkills.map((skill, index) => (
              <div key={index}>
                <div 
                  className={`skill-item ${selectedSkill?.name === skill.name ? 'active' : ''}`}
                  onClick={() => handleSkillClick(skill)}
                >
                  <span>{skill.name}</span>
                </div>
                {selectedSkill?.name === skill.name && (
                  <div className="skill-description">
                    <p>{selectedSkill.description}</p>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>

        <div className="skill-category">
          <h3>Project Management</h3>
          <div className="skill-list">
            {pmSkills.map((skill, index) => (
              <div key={index}>
                <div 
                  className={`skill-item ${selectedSkill?.name === skill.name ? 'active' : ''}`}
                  onClick={() => handleSkillClick(skill)}
                >
                  <span>{skill.name}</span>
                </div>
                {selectedSkill?.name === skill.name && (
                  <div className="skill-description">
                    <p>{selectedSkill.description}</p>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>

        <div className="skill-category">
          <h3>Tools & Platforms</h3>
          <div className="skill-list">
            {tools.map((tool, index) => (
              <div key={index}>
                <div 
                  className={`skill-item ${selectedSkill?.name === tool.name ? 'active' : ''}`}
                  onClick={() => handleSkillClick(tool)}
                >
                  <span>{tool.name}</span>
                </div>
                {selectedSkill?.name === tool.name && (
                  <div className="skill-description">
                    <p>{selectedSkill.description}</p>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

export default Skills;
